def solve(grid):
    from collections import Counter, defaultdict, deque

    H, W = len(grid), len(grid[0])

    def dominant_color(sub):
        cnt = Counter()
        for row in sub:
            cnt.update(row)
        return cnt.most_common(1)[0][0]

    def get_components(sub, bg):
        h, w = len(sub), len(sub[0])
        seen = [[False] * w for _ in range(h)]
        comps = []
        for r in range(h):
            for c in range(w):
                if seen[r][c] or sub[r][c] == bg:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and not seen[nx][ny] and sub[nx][ny] != bg:
                            seen[nx][ny] = True
                            q.append((nx, ny))
                comps.append(cells)
        return comps

    def crop_horizontal(top, bottom):
        return [row[:] for row in top], [row[:] for row in bottom]

    def crop_vertical(left, right):
        return [row[:] for row in left], [row[:] for row in right]

    def try_build(source, target):
        hs, ws = len(source), len(source[0])
        ht, wt = len(target), len(target[0])

        bg_s = dominant_color(source)
        bg_t = dominant_color(target)

        comps = get_components(source, bg_s)
        if not comps:
            return None

        target_pos = defaultdict(list)
        for r in range(ht):
            for c in range(wt):
                v = target[r][c]
                if v != bg_t:
                    target_pos[v].append((r, c))

        out = [[bg_t for _ in range(wt)] for _ in range(ht)]
        matched = 0

        for cells in comps:
            minr = min(r for r, c in cells)
            maxr = max(r for r, c in cells)
            minc = min(c for r, c in cells)
            maxc = max(c for r, c in cells)

            colors = set(source[r][c] for r, c in cells)
            placed = False

            for key_color in colors:
                if key_color not in target_pos:
                    continue

                rel_key = sorted((r - minr, c - minc) for r, c in cells if source[r][c] == key_color)
                tgt = sorted(target_pos[key_color])

                if len(rel_key) != len(tgt):
                    continue

                off_r = tgt[0][0] - rel_key[0][0]
                off_c = tgt[0][1] - rel_key[0][1]
                shifted = sorted((dr + off_r, dc + off_c) for dr, dc in rel_key)

                if shifted != tgt:
                    continue

                ok = True
                for r, c in cells:
                    rr = r - minr + off_r
                    cc = c - minc + off_c
                    if not (0 <= rr < ht and 0 <= cc < wt):
                        ok = False
                        break
                if not ok:
                    continue

                for r, c in cells:
                    rr = r - minr + off_r
                    cc = c - minc + off_c
                    out[rr][cc] = source[r][c]

                matched += 1
                placed = True
                break

            if not placed:
                return None

        return matched, out

    candidates = []

    if H % 2 == 0:
        top = grid[: H // 2]
        bottom = grid[H // 2 :]
        for source, target in (crop_horizontal(top, bottom), crop_horizontal(bottom, top)):
            res = try_build(source, target)
            if res is not None:
                candidates.append(res)

    if W % 2 == 0:
        left = [row[: W // 2] for row in grid]
        right = [row[W // 2 :] for row in grid]
        for source, target in (crop_vertical(left, right), crop_vertical(right, left)):
            res = try_build(source, target)
            if res is not None:
                candidates.append(res)

    if not candidates:
        return [row[:] for row in grid]

    candidates.sort(key=lambda x: x[0], reverse=True)
    return candidates[0][1]

